@inherits UmbracoViewPage<BlogFrontPage>
@{
    Layout = "_Layout.cshtml";
    ViewData["Title"] = null;
    var posts = Model.Children<BlogPost>().OrderByDescending(p => p.PublishDate).ToList();
}

<section class="mx-auto max-w-5xl px-6 pt-14 pb-6">
    <h1 class="text-5xl font-extrabold tracking-tight text-slate-900">@Model.Title</h1>
    @if (!string.IsNullOrWhiteSpace(Model.Intro))
    {
        <p class="mt-4 max-w-2xl text-xl text-slate-600">@Model.Intro</p>
    }
</section>

@await Html.GetBlockGridHtmlAsync(Model, "blocks")

<section class="mx-auto mt-10 max-w-5xl px-6">
    <h2 class="mb-6 text-2xl font-bold text-slate-900">Latest posts</h2>
    <div class="grid gap-8 md:grid-cols-2">
        @foreach (var post in posts)
        {
            <article class="overflow-hidden rounded-xl border border-slate-200 shadow-sm transition hover:shadow-md">
                <a href="@post.Url()" class="block">
                    @if (post.ListingImage is { } listingImage)
                    {
                        <img src="@listingImage.GetCropUrl(width: 800, height: 450)" alt="@post.Title" class="aspect-video w-full object-cover" loading="lazy" />
                    }
                    <div class="p-6">
                        <time datetime="@post.PublishDate.ToString("yyyy-MM-dd")" class="text-sm text-slate-500">@post.PublishDate.ToString("MMMM d, yyyy")</time>
